<?php

declare(strict_types=1);

$root = dirname($root, 2);
require $root . '/app/V2/Database.php';
require $root . '/app/V2/RuntimeStatus.php';
require $root . '/app/V2/Schema.php';
require $root . '/app/V2/Alerts/AlertService.php';
use LittyWatch\V2\Database;
use LittyWatch\V2\RuntimeStatus;
use LittyWatch\V2\Schema;
use LittyWatch\V2\Alerts\AlertService;
function age(?int $seconds): string { if($seconds===null)return 'Nooit'; if($seconds<60)return $seconds.' sec'; if($seconds<3600)return floor($seconds/60).' min'; if($seconds<86400)return floor($seconds/3600).' uur'; return floor($seconds/86400).' dagen'; }
function state(?int $age, int $warn): string { if($age===null)return 'lw-bad'; return $age<=$warn?'lw-ok':($age<=$warn*3?'lw-warn':'lw-bad'); }
$error=null;$pdo=null;$counts=[];
try{$pdo=Database::connect($root);Schema::ensure($pdo);(new AlertService($pdo))->install();foreach(['messages','structured_offers','market_intelligence','watchlist','alerts','alert_events','market_snapshots','asset_imports','item_assets'] as $t){$exists=(bool)$pdo->query("SELECT 1 FROM sqlite_master WHERE type='table' AND name=".$pdo->quote($t)." LIMIT 1")->fetchColumn();$counts[$t]=$exists?(int)$pdo->query('SELECT COUNT(*) FROM '.$t)->fetchColumn():null;}}catch(Throwable $e){$error=$e->getMessage();}
$jobs=['collector'=>300,'intelligence'=>900,'alerts'=>900,'snapshots'=>7200];$statuses=[];foreach($jobs as $name=>$warn){$s=RuntimeStatus::read($root,$name);$statuses[$name]=['data'=>$s,'age'=>RuntimeStatus::ageSeconds($s),'warn'=>$warn];}
$checks=['PHP'=>PHP_VERSION,'PDO SQLite'=>extension_loaded('pdo_sqlite')?'OK':'Ontbreekt','Database'=>is_file($root.'/data/market.sqlite')?'Aanwezig':'Ontbreekt','Data schrijfbaar'=>is_writable($root.'/data')?'Ja':'Nee','Logs schrijfbaar'=>is_writable($root.'/logs')?'Ja':'Nee'];
?><!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>LittyWatch  Health</title><link rel="stylesheet" href="/assets/v2/platform.css?v=310"><style>body{margin:0;background:radial-gradient(circle at 15% 0,#1a2435 0,#080b10 42%);color:#eef2f8;font:14px/1.5 Inter,system-ui,sans-serif}.wrap{max-width:1450px;margin:auto;padding:28px}.top{display:flex;justify-content:space-between;gap:20px}.eyebrow{font-size:11px;color:#d9b870;font-weight:900;letter-spacing:.16em}h1{margin:5px 0}.muted{color:#9eabba}nav a{color:#9eabba;text-decoration:none;margin-left:14px}.panel{background:rgba(18,24,36,.95);border:1px solid #293548;border-radius:15px;overflow:hidden;margin-top:18px}.panel h2{margin:0;padding:16px 18px;border-bottom:1px solid #293548}.table{width:100%;border-collapse:collapse}.table td,.table th{padding:11px 16px;border-bottom:1px solid rgba(41,53,72,.7);text-align:left}.error{padding:12px 14px;background:rgba(239,145,145,.12);color:#ef9191;border-radius:10px;margin-top:16px}@media(max-width:700px){.wrap{padding:17px}.top{flex-direction:column}nav a{margin:0 12px 0 0}}</style></head><body><main class="wrap"><header class="top"><div><div class="eyebrow">LITTYWATCH </div><h1>Productiecontrole <span class="lw-version"></span></h1><div class="muted">Database, cronjobs en kernonderdelen in één overzicht.</div></div><nav><a href="/">Command Center</a><a href="/alerts">Alerts</a><a href="/watchlist">Watchlist</a><a href="/assets">Assets</a></nav></header><?php if($error):?><div class="error"><?=h($error)?></div><?php endif;?><section class="panel"><h2>Cron- en servicestatus</h2><div class="lw-health-grid" style="padding:16px"><?php foreach($statuses as $name=>$row):?><div class="lw-health-card"><small><?=h(ucfirst($name))?></small><strong class="<?=state($row['age'],$row['warn'])?>"><?=h(age($row['age']))?> geleden</strong><span class="muted"><?=h($row['data']['message']??($row['data']['ok']??null?'OK':'Nog niet uitgevoerd'))?></span></div><?php endforeach;?></div></section><section class="panel"><h2>Databestand</h2><div class="lw-health-grid" style="padding:16px"><?php foreach($counts as $table=>$count):?><div class="lw-health-card"><small><?=h($table)?></small><strong><?= $count===null?'Ontbreekt':number_format($count,0,',','.') ?></strong></div><?php endforeach;?></div></section><section class="panel"><h2>Serverchecks</h2><table class="table"><?php foreach($checks as $label=>$value):?><tr><td><?=h($label)?></td><td><?=h($value)?></td></tr><?php endforeach;?></table></section><section class="panel"><h2>Cron instellen</h2><div style="padding:16px"><p class="muted">De alertstatus verschijnt pas nadat de CLI-taak minimaal één keer heeft gedraaid.</p><pre style="white-space:pre-wrap;background:#080b10;border:1px solid #293548;border-radius:10px;padding:13px;color:#eef2f8">*/5 * * * * /usr/bin/php <?=h($root)?>/cron/evaluate-alerts.php &gt;&gt; <?=h($root)?>/logs/alerts-cron.log 2&gt;&amp;1</pre><p class="muted">Handmatig testen via SSH:</p><pre style="white-space:pre-wrap;background:#080b10;border:1px solid #293548;border-radius:10px;padding:13px;color:#eef2f8">/usr/bin/php <?=h($root)?>/cron/evaluate-alerts.php</pre></div></section></main><script src="/assets/v2/platform.js?v=310"></script>
</body></html>